<?php $edit=$payment!==null;$val=static fn($k,$d='')=>e((string)($payment[$k]??$d));?><div class="page-header mb-4"><h2 class="page-title"><?=$edit?'تعديل مسودة دفعة':'إضافة دفعة مورد'?></h2></div><form method="post" action="<?=$edit?'/supplier-payments/'.(int)$payment['id'].'/edit':'/supplier-payments'?>"><input type="hidden" name="_token" value="<?=e($csrfToken)?>"><div class="card"><div class="card-body"><div class="row g-3"><div class="col-md-6"><label class="form-label required">فاتورة المورد</label><select class="form-select" name="supplier_invoice_id" required <?=$edit?'disabled':''?>><?php foreach($references['invoices']as$x):$selected=(int)($payment['supplier_invoice_id']??$selectedInvoice)===(int)$x['id'];?><option value="<?=(int)$x['id']?>" <?=$selected?'selected':''?>><?=e($x['invoice_code'].' - '.$x['vendor_name'].' - '.$x['total_amount'])?></option><?php endforeach;?></select><?php if($edit):?><input type="hidden" name="supplier_invoice_id" value="<?=(int)$payment['supplier_invoice_id']?>"><?php endif;?></div><div class="col-md-3"><label class="form-label required">تاريخ الدفع</label><input class="form-control" type="date" name="payment_date" required value="<?=$val('payment_date',date('Y-m-d'))?>"></div><div class="col-md-3"><label class="form-label required">المبلغ</label><input class="form-control" type="number" min="0.01" step="0.01" name="amount" required value="<?=$val('amount')?>"></div><div class="col-md-4"><label class="form-label required">طريقة الدفع</label><select class="form-select" name="payment_method"><?php foreach(['cash'=>'نقدي','bank_transfer'=>'تحويل بنكي','cheque'=>'شيك','other'=>'أخرى']as$k=>$v):?><option value="<?=$k?>" <?=($payment['payment_method']??'')===$k?'selected':''?>><?=$v?></option><?php endforeach;?></select></div><div class="col-md-4"><label class="form-label">المرجع</label><input class="form-control" name="reference" maxlength="190" value="<?=$val('reference')?>"></div><div class="col-md-4"><label class="form-label">ملاحظات</label><textarea class="form-control" name="notes"><?=$val('notes')?></textarea></div></div></div><div class="card-footer text-end"><button class="btn btn-primary">حفظ المسودة</button></div></div></form>
